"""Execution terms. Memory/file/coordination terms belong to the other authors."""
GLOSSARY = [
 ('Операционная система (ОС)', 'Системное программное обеспечение, организующее исполнение приложений, распределение ресурсов и доступ к защищённым объектам. Ядро — часть ОС, а не все её программы.'),
 ('Ресурс', 'Ограниченная возможность или объект, нужный для работы: время CPU, память, устройство, открытый объект. Требуется определить владельца, допустимое использование и правила выдачи другим участникам.'),
 ('Приложение', 'Программа, выполняющая выбранную предметную функцию. Может работать без окна и получать системные услуги по предусмотренным интерфейсам.'),
 ('Программа', 'Сохранённое описание команд и данных с правилами подготовки исполнения. Один образ программы может обслуживать несколько разных процессов.'),
 ('Процесс (process)', 'Экземпляр исполнения под управлением ОС с ресурсами и свойствами: адресным пространством, открытыми объектами, средой запуска и учётными данными. Может содержать несколько потоков.'),
 ('Поток исполнения (thread)', 'Отдельное планируемое продолжение с регистрами, стеком и состоянием. Разделение ресурсов с другими потоками определяется системой; поток не является аппаратным CPU или потоком байтов.'),
 ('Ядро ОС (kernel)', 'Защищённая часть управляющей системы, организующая доступ к ресурсам, обработку событий и системные услуги. Состоит из кода, исполняемого аппаратными CPU; отличается от физического ядра процессора.'),
 ('Пользовательский режим', 'Аппаратный режим исполнения с ограничением защищённых действий. Программа использует разрешённую память и предусмотренные точки обращения к ядру.'),
 ('Привилегированный режим', 'Режим с доступом к определённым управляющим действиям CPU. Код ядра всё равно проверяет права операции от имени конкретного участника; режим не равен имени root.'),
 ('Механизм и политика', 'Механизм предоставляет способ действия, политика выбирает, кому, когда и при каких условиях его применить. Один аппаратный механизм может обслуживать разные политики ОС.'),
 ('Системная программа', 'Программа окружения ОС по своему назначению: например, менеджер служб. Название не означает обязательное исполнение её команд в привилегированном режиме CPU.'),
 ('Состояние', 'Значения и связи, от которых зависит следующий допустимый шаг. У потока это, например, PC/SP, режим и причина ожидания; у открытия — ссылка на файл, позиция и флаги. Текущие значения CPU и сохранённая запись потока относятся к разным моментам.'),
 ('Владение ресурсом', 'Договор ответственности за использование и завершение жизни ресурса. Передача владения отличается от копирования значения и от создания дополнительной разделяемой ссылки.'),
 ('Договор операции', 'Определение допустимых входов, результатов, ошибок и изменений состояния. Успешный отдельный вызов подтверждает только обещанное этим договором свойство.'),
 ('Системный вызов (system call)', 'Намеренное обращение приложения к операции ядра по двоичному договору номера, аргументов, результата и сохранения состояния. Сам вход не создаёт новый процесс.'),
 ('Исключение процессора', 'Событие, связанное с текущей командой, например нарушением отображения памяти. Правила архитектуры и обработчика определяют, можно ли исправить состояние и повторить команду.'),
 ('Аппаратное прерывание (IRQ)', 'Уведомление CPU о предусмотренном аппаратном событии. Текущий прерванный поток не обязан быть владельцем завершившейся операции.'),
 ('Trap (ловушка)', 'Термин с зависящим от архитектуры значением. В книге вместо неявной универсальной классификации отдельно названы намеренный вызов, исключение текущей команды и аппаратное уведомление.'),
 ('Функция', 'Участок программы с заданными входами, действиями и способом вернуть управление вызывающему коду. Обычный вызов функции сам по себе не меняет процесс и аппаратные полномочия.'),
 ('PC и SP', 'PC обозначает положение исполнения по правилам выбранной ISA; SP — положение вершины стека. Текущие регистры CPU отличаются от сохранённых полей остановленного продолжения.'),
 ('Инвариант', 'Условие, которое корректный алгоритм сохраняет в заранее названных точках наблюдения. Переходы и границы этих точек нужно определить: например, поток не исполняется одновременно на двух CPU, а защищённая структура согласована при выдаче её следующему владельцу.'),
 ('API — программный интерфейс', 'Набор доступных программе операций и правил их вызова: входы, результаты, ошибки и наблюдаемые изменения. Двоичное представление аргументов и взаимодействия готового кода уточняется ABI.'),
 ('Монотонные часы', 'Шкала измерения интервалов, в которой более позднее чтение не даёт меньшее значение. Разрешение, точность и учёт приостановки машины зависят от выбранного интерфейса.'),
 ('Идемпотентность запроса', 'Повтор с той же смысловой идентичностью не добавляет ещё один эффект по установленным правилам. Для изменения счётчика требуется согласованно сохранять идентичность запроса и его результат; одно совпавшее число этого не обеспечивает.'),
 ('ABI — двоичный интерфейс', 'Соглашение готового кода о представлении аргументов/результатов, регистрах, входе и сохраняемом состоянии. ABI функции и системного вызова могут различаться на одном CPU; набор машинных операций задаёт ISA.'),
 ('Библиотека', 'Код, предоставляющий функции другим программам. Библиотечный вызов может выполнить несколько системных операций, одну либо обойтись пользовательскими вычислениями.'),
 ('Обёртка системного вызова', 'Пользовательская функция, подготавливающая аргументы по ABI ядра и представляющая результат по договору библиотеки или языка.'),
 ('errno', 'Причина определённой ошибки в интерфейсе библиотеки C. Проверяется после результата, для которого обещан отказ; прежнее ненулевое значение само по себе не означает новую ошибку.'),
 ('Продолжение исполнения', 'Сведения о том, откуда и с каким состоянием разрешено продолжить работу. При незавершённом системном вызове нужно сохранить и его внутреннее продолжение, а не только адрес пользователя.'),
 ('Кадр входа (entry frame)', 'В учебном ABI — защищённая запись пользовательских PC/SP/регистров и режима для возврата. Это entry frame, а не физический кадр памяти. Автоматическая аппаратная часть и дополнительные сохранения ядра различаются между архитектурами.'),
 ('Контекст исполнения', 'Состояние, достаточное для продолжения потока: регистры, стек, связанные адресные и системные свойства. Вся память процесса не копируется при каждом переключении.'),
 ('Смена режима', 'Переход между аппаратными уровнями исполнения. Может произойти у того же потока без передачи CPU другому процессу.'),
 ('Переключение контекста', 'Передача исполнения другому продолжению с сохранением и восстановлением нужного состояния. Отличается от простого входа в ядро и может иметь косвенную цену из-за локальности.'),
 ('Стек ядра', 'Защищённая память для предусмотренного пути ядра и его продолжения. Конкретная привязка стеков к потокам/CPU и обработчикам зависит от реализации.'),
 ('Образ программы', 'Код, данные и описания, используемые при подготовке исполнения. Его версия и байты не совпадают по смыслу с идентичностью живого процесса.'),
 ('Загрузчик', 'Код подготовки исполняемого представления и начального продолжения. Может включать системную и пользовательскую части; наличие файла не доказывает успешную загрузку.'),
 ('Runtime — среда выполнения языка (language runtime)', 'Код поддержки объектов языка: распределения памяти, пользовательских задач и других действий среды. Например, runtime Go управляет горутинами и памятью программы. Он работает поверх ресурсов ОС; среда выполнения языка и ядро ОС имеют разные обязанности.'),
 ('Аргументы запуска', 'Входные параметры новой программы по договору её запуска. Представление списка аргументов Unix отличается от строки и разбора конкретного Windows API.'),
 ('Окружение запуска', 'Переданные программе параметры среды, часто строковые пары имя=значение. Не заменяют учётные данные ядра и не обновляют автоматически другие процессы.'),
 ('Текущий каталог', 'Опора разрешения обычных относительных путей процесса. Не обязан совпадать с каталогом исполняемого файла или исходника.'),
 ('Идентификатор процесса (PID)', 'Числовое имя процесса в предусмотренной области видимости. Может переиспользоваться, поэтому для долгого наблюдения нужны контекст и время жизни объекта.'),
 ('Родитель и ребёнок', 'Отношение создающего участника и нового процесса по договору ОС. Варианты наследования и ожидания определяются конкретным интерфейсом.'),
 ('Замена образа', 'Подготовка другой программы внутри предусмотренной идентичности существующего процесса. При успехе старое пользовательское продолжение не возобновляется.'),
 ('fork', 'Unix-подобный интерфейс создания ребёнка с отдельным продолжением и установленным наследованием. Общность открытых объектов отличается от логической независимости частной памяти.'),
 ('execve', 'Linux/Unix-интерфейс замены образа вызывающего процесса с выбранными аргументами и окружением. Успешный вызов не возвращается к старой программе.'),
 ('CreateProcessW', 'Windows API создания процесса и первичного потока с явными входами. Успех создания не подтверждает завершение последующей инициализации или готовность службы.'),
 ('Ожидание завершения', 'Получение предусмотренного результата изменения состояния ребёнка или управляемого объекта. Отправка просьбы остановиться и фактическое завершение — разные события.'),
 ('Зомби-процесс', 'В Unix-подобном примере — завершившийся экземпляр с ещё не полученной записью результата. Пользовательские команды уже не исполняются.'),
 ('Код завершения', 'Компактное описание обычного исхода по договору программы и интерфейса ожидания. Завершение внешним событием может передаваться отдельно.'),
 ('Планировщик', 'Средства и политика выбора готового исполнителя для допустимого CPU. Учитываемые состояния и предпочтения зависят от конкретной ОС.'),
 ('Готовый поток', 'Поток, способный продолжить работу, но пока не обязательно получивший CPU. Отличается от ожидающего внешнее событие и от готовности прикладной службы.'),
 ('Очередь готовых', 'Учёт допустимых кандидатов на исполнение с определённым порядком или иной политикой выбора. Не равна числу всех процессов машины.'),
 ('Ожидающий поток', 'Исполнитель, которому для продолжения нужно событие: данные, освобождение объекта или результат работы. Изменение приоритета само по себе не создаёт это событие.'),
 ('Пробуждение', 'Переход к возможности снова претендовать на CPU после нужного изменения. Не обещает немедленного исполнения или исключительного владения любым объектом.'),
 ('Вытеснение', 'Передача CPU другому готовому продолжению до добровольного ожидания текущего. Допустимые точки и политика определяются ядром.'),
 ('Квант времени', 'В простой политике — ограниченная непрерывная порция исполнения. Не является доказательством одинакового фиксированного кванта всех реальных классов планирования.'),
 ('FCFS', 'Учебная политика обслуживания в порядке поступления без вытеснения текущей CPU-порции. Короткая работа может ждать ранее начавшуюся длинную.'),
 ('Round-robin', 'Круговой обход готовых участников с заданной порцией времени. Порядок одновременных поступлений/пробуждений/исчерпания кванта должен быть определён.'),
 ('Справедливость планирования', 'Названное правило распределения обслуживания между определёнными участниками: например, пропорционально весам среди готовых. Слово не задаёт универсальный алгоритм.'),
 ('Приоритет', 'Предпочтение выбора по договору планировщика. Не является самостоятельной мерой скорости кода и не гарантирует срок выполнения.'),
 ('Голодание', 'Неограниченное откладывание готового или допустимого участника, пока другие получают обслуживание. Причину ищут в правилах выбора и допуска; конечная пауза ожидания ещё не означает голодания.'),
 ('Срок (deadline, дедлайн)', 'Момент, к которому требуется определённый результат. Что делать после опоздания — принять поздний результат, прекратить ожидание или инициировать отмену — задаёт операция. Тайм-аут ограничивает длительность отдельного ожидания, а не доказывает, что начатое действие отменено. Общий момент сохраняют при последовательных ожиданиях: новый этап не получает заново полный исходный бюджет.'),
 ('SMP', 'Совместная организация нескольких CPU с общей системой управления и соответствующей памятью. Размещение и согласование между исполнителями становятся частью планирования.'),
 ('Привязка к CPU (affinity)', 'Предпочтение или допустимый набор CPU по конкретному договору. Жёсткий набор может оставить работу в очереди при свободном запрещённом ей CPU.'),
 ('Балансировка нагрузки', 'Перераспределение допустимой работы между исполнителями по выбранной оценке. Равное число потоков не означает равную потребность в CPU или памяти.'),
 ('Миграция потока', 'Продолжение исполнения на другом CPU. Идентичность потока сохраняется, но локальность кешей и путь к памяти могут измениться.'),
 ('Локальность исполнения', 'Близость используемых кода, данных и аппаратных ресурсов во времени и пространстве. Сохранение места может экономить обращения, но узкая привязка добавляет очередь.'),
 ('Масштабируемость', 'Изменение полезного результата при добавлении ресурсов в определённой нагрузке. Последовательная доля, согласование и общие устройства ограничивают идеальное ускорение.'),
 ('Служба', 'Длительно предоставляемая функция программы или группы программ. Её готовность, состояние и сохраняемые обязательства не сводятся к наличию одного процесса.'),
 ('Менеджер служб', 'Пользовательская управляющая программа запуска, наблюдения и остановки компонентов. Работает через механизмы ОС и не обязана быть ядром.'),
 ('Готовность службы', 'Подтверждённая способность выполнять оговорённую прикладную функцию. Создание процесса или открытие порта может подтверждать только часть подготовки.'),
 ('Зависимость запуска', 'Требование результата или присутствия другого компонента. Отдельно задают включение компонента, порядок действий и ожидаемую готовность.'),
 ('Дренирование', 'Ожидание окончания ранее принятой работы после прекращения новой. Требует предела и договора об исходе незавершённых операций.'),
 ('Корректное завершение', 'Протокол прекращения приёма, обработки активных обязательств, сохранения нужного состояния и получения результата выхода.'),
 ('Нагрузка (workload)', 'Входы, их распределение, поступления и одновременно действующие участники. Для сравнения нужно сохранять полезный договор и учитывать ошибки.'),
 ('Исходное измерение (baseline)', 'Результат до изменения при записанных условиях и корректности. Нужен для отличия улучшения исполнения от смены входов или требований.'),
 ('Прошедшее время (wall time)', 'Длительность между названными событиями по подходящей шкале часов. Включает ожидания. Измерение интервала монотонными часами и чтение календарного времени — разные задачи.'),
 ('CPU-время', 'Время исполнения, учтённое на CPU для указанного процесса, потока или группы. Параллельные исполнители суммируются, поэтому результат может превышать прошедший интервал; область учёта указывается отдельно.'),
 ('Пользовательское и системное время', 'Категории процессорного учёта обычного кода и определённой работы ядра. Не обязательно включают всю асинхронную стоимость обслуживания процесса во всей машине.'),
 ('Счётчик и скорость', 'Счётчик накапливает события или время; скорость получают из приращения за интервал. Перезапуск или изменение объекта может нарушить вычитание.'),
 ('Процессорная цена операции', 'Количество учтённого CPU-времени на один проверенный полезный результат. Не равно полной задержке с ожиданием.'),
 ('Критический путь', 'Цепочка зависимостей, задающая самый ранний возможный результат. Её длительность отличается от суммы работы всех параллельных участников.'),
 ('Накладные расходы наблюдения', 'Работа и изменения режима исполнения из-за измерения, трассировки и сбора данных. Сопоставляются с достаточностью нужного свидетельства.'),
 ('Неизвестный исход', 'Состояние наблюдателя, который не получил подтверждение и не может различить выполненное действие и невыполненное. Само отсутствие ответа не разрешает безопасный повтор изменения.'),
 ('Восстановление', 'Получение допустимого состояния из сохранившихся данных и свидетельств по предусмотренному протоколу. Простой перезапуск не доказывает восстановление обязательств.'),
 ('Пауза повторения', 'Управление частотой новых попыток после допустимого отказа. Помогает не усиливать перегрузку, но не делает недопустимую повторную операцию корректной.'),
]
# The optional helper is invoked as an explicitly documented Python script.
# Do not replace the library-wide python3/fork/exec/sysctl/etc. command cards.
COMMANDS = []
